## phospho row id  ENSG|ENSP|S123|peptide|n  ->  data.table of the five fields
parse_phospho_id <- function(x) {
  p <- tstrsplit(x, "|", fixed = TRUE)
  stopifnot(length(p) == 5L)
  data.table(ensg = p[[1]], ensp = p[[2]], site = p[[3]], peptide = p[[4]], n = p[[5]])
}
phospho_probe <- function(sym, site) paste0(sym, "_", site, ".phospho")

## keep exactly one id per symbol: the one with the most non-NA values
## (ties: smallest id). id must be distinct. Returns logical keep, input order.
pick_by_symbol <- function(id, sym, nn) {
  d <- data.table(i = seq_along(id), id = id, sym = sym, nn = nn)
  setorder(d, sym, -nn, id)
  d[, keep := seq_len(.N) == 1L, by = sym]
  out <- logical(length(id)); out[d$i] <- d$keep
  out
}

## phospho: per (sym, site) keep the ENSP with the most non-NA values (ties:
## smallest ENSP). d has sym, site, ensp, nn (one row per distinct triple).
## Returns logical keep, input order.
pick_ensp <- function(d) {
  d <- as.data.table(d)[, .(sym, site, ensp, nn)]
  d[, i := .I]
  setorder(d, sym, site, -nn, ensp)
  d[, keep := seq_len(.N) == 1L, by = .(sym, site)]
  out <- logical(nrow(d)); out[d$i] <- d$keep
  out
}

## fmut string in TCGA's format
fmut_value <- function(hugo, aachange, vclass) {
  aa <- aachange
  aa[is.na(aa) | !nzchar(aa)] <- "NA"
  gsub("*", "s", paste(hugo, aa, vclass, sep = "_"), fixed = TRUE)
}

## T2 sample id from a column name.
##   kind "tumor"  : file is a tumor file; id = case
##   kind "normal" : file is a normal file; id = case_N
##   kind "tpm"    : suffixed (_T/_A) when any column carries a suffix, else bare
## Returns data.table(col, case, sample, normal, keep) -- keep = case in `cases`
## (and, for tpm in a suffixed file, the column has a suffix).
sample_ids_for <- function(cols, kind, cases, bare_ok = NULL) {
  if (kind == "tpm") {
    suff <- any(grepl("_[TA]$", cols))
    if (suff) {
      has <- grepl("_[TA]$", cols)
      case <- ifelse(has, sub("_[TA]$", "", cols), cols)
      normal <- has & grepl("_A$", cols)
      ok <- has & case %in% cases
    } else {
      case <- cols; normal <- rep(FALSE, length(cols)); ok <- case %in% cases
      if (!is.null(bare_ok)) ok <- ok & cols %in% bare_ok   # bare ids: tumor iff a column of the RNA UQ Tumor file
    }
  } else {
    case <- cols; normal <- rep(kind == "normal", length(cols)); ok <- case %in% cases
  }
  data.table(col = cols, case = case, sample = ifelse(normal, paste0(case, "_N"), case),
             normal = normal, keep = ok)
}

## clinical column names: non-alphanumerics -> "_", squeeze, strip
norm_clin_names <- function(x) {
  x <- gsub("[^A-Za-z0-9_]+", "_", x)
  x <- gsub("_+", "_", x)
  gsub("^_+|_+$", "", x)
}
## append _clin to names equal to a probe name or a reserved word
clin_collide <- function(nms, probe_names, reserved = c("cohort", "subtype", "lcohort",
                         "sample", "case", "cancer_type", "study", "sample_type")) {
  hit <- nms %in% probe_names | nms %in% reserved
  nms[hit] <- paste0(nms[hit], "_clin")
  nms
}
