## event column to numeric 0/1 (Yes/No accepted)
coerce_event <- function(x) {
  y <- tolower(trimws(x))
  v <- ifelse(y %in% c("yes", "true"), "1", ifelse(y %in% c("no", "false"), "0", y))
  suppressWarnings(as.numeric(v))
}

