## --- readers ------------------------------------------------------------------
nfields <- function(l) length(strsplit(l, "\t", fixed = TRUE)[[1]]) + (substring(l, nchar(l)) == "\t")
## header ids of a matrix file (without the corner cell)
head_ids <- function(f) {
  ls <- sub("\r$", "", readLines(f, n = 2, warn = FALSE))
  hd <- strsplit(ls[1], "\t", fixed = TRUE)[[1]]
  short <- nfields(ls[2]) == length(hd) + 1
  list(ids = if (short) hd else hd[-1], short = short)
}
## matrix file -> list(ids = row ids, M = numeric matrix [rows x samples], nonfinite = count)
read_mat <- function(f, nrows = Inf, rows = NULL) {
  hi <- head_ids(f)
  dt <- if (hi$short) fread(f, header = FALSE, skip = 1, sep = "\t", quote = "", nrows = nrows, na.strings = c("NA", ""))
        else fread(f, header = TRUE, sep = "\t", quote = "", nrows = nrows, na.strings = c("NA", ""))
  ids <- sub("\r$", "", as.character(dt[[1]])); dt[, (1) := NULL]
  stopifnot(ncol(dt) == length(hi$ids))
  for (j in seq_along(dt)) if (!is.numeric(dt[[j]])) set(dt, j = j, value = suppressWarnings(as.numeric(dt[[j]])))
  M <- as.matrix(dt); rm(dt)
  colnames(M) <- hi$ids; rownames(M) <- NULL
  nonfin <- sum(is.infinite(M) | is.nan(M), na.rm = TRUE)
  M[!is.finite(M)] <- NA
  stopifnot(!anyDuplicated(ids))
  list(ids = ids, M = M, nonfinite = nonfin)
}
read_ids <- function(f) {
  hi <- head_ids(f)
  ids <- fread(f, header = !hi$short, skip = if (hi$short) 1 else 0, select = 1, sep = "\t", quote = "")[[1]]
  sub("\r$", "", as.character(ids))
}

