read_meta_raw <- function(f) {
  dt <- fread(f, sep = "\t", header = TRUE, quote = "", colClasses = "character", na.strings = c("NA", ""))
  names(dt) <- sub("\r$", "", names(dt))
  dt[, (names(dt)) := lapply(.SD, function(x) sub("\r$", "", x))]
  types <- unlist(dt[1]); dt <- dt[-1]
  stopifnot(names(dt)[1] == "idx", !anyDuplicated(dt$idx))
  list(dt = dt, types = types[-1])
}
