COLMAP <- list()   # [[type]][[cohort]] : list of column maps per file
add_cols <- function(type, C, fkey, kind) {
  f <- FL[[C]][[fkey]]
  if (is.na(f) || !file.exists(f)) return(NULL)
  ids <- head_ids(f)$ids
  ids <- sub("\r$", "", ids)
  bare_ok <- NULL
  if (kind == "tpm" && !any(grepl("_[TA]$", ids))) {       # bare-id TPM file (BRCA, COAD, OV)
    stopifnot(file.exists(FL[[C]]$rna_uq)); bare_ok <- sub("\r$", "", head_ids(FL[[C]]$rna_uq)$ids)
  }
  m <- sample_ids_for(ids, kind, CASES[[C]], bare_ok)
  nd <- sum(!m$keep)
  if (nd) drop_log(sprintf("%s columns not in the case universe (%s %s)", type, C, kind), nd,
                   paste(head(m$col[!m$keep], 4), collapse = ","))
  m <- m[keep == TRUE]
  stopifnot(!anyDuplicated(m$sample))
  m[, `:=`(cancer_type = C, type = type, fkey = fkey)]
  COLMAP[[type]][[paste(C, fkey)]] <<- m
  NULL
}
