probe_key_env <- new.env(hash = TRUE); probe_type_env <- new.env(hash = TRUE)
probe_names <- character(0)
assign_keys <- function(nms, type) {
  k <- unlist(mget(nms, envir = probe_key_env, ifnotfound = NA_integer_), use.names = FALSE)
  new <- is.na(k)
  if (any(new)) {
    u <- unique(nms[new])
    kk <- length(probe_names) + seq_along(u)
    list2env(setNames(as.list(kk), u), envir = probe_key_env)
    list2env(setNames(as.list(rep(type, length(u))), u), envir = probe_type_env)
    probe_names <<- c(probe_names, u)
    k <- unlist(mget(nms, envir = probe_key_env), use.names = FALSE)
  }
  ty <- unlist(mget(nms, envir = probe_type_env), use.names = FALSE)
  if (any(ty != type)) stop("probe with two types: ", paste(head(nms[ty != type], 3), collapse = ","))
  k
}
NROWS <- c(); bump <- function(tbl, type, n) NROWS[paste(tbl, type)] <<- sum(NROWS[paste(tbl, type)], n, na.rm = TRUE)

## M: numeric matrix rows = probe names, cols = sample ids
insert_mat <- function(M, type, keep) {
  sk <- sample_key[colnames(M)]; stopifnot(!anyNA(sk))
  nr <- nrow(M); tot <- 0
  if (nr == 0) { bump("tcgai", type, 0); return(0) }
  for (lo in seq(1, nr, by = CHUNK)) {
    hi <- min(lo + CHUNK - 1L, nr)
    sub <- M[lo:hi, , drop = FALSE]
    pk <- assign_keys(rownames(sub), type)
    idx <- which(keep(sub))
    if (length(idx)) {
      r <- (idx - 1L) %% nrow(sub) + 1L; c <- (idx - 1L) %/% nrow(sub) + 1L
      dbAppendTable(con, "tcgai", data.frame(samplekey = unname(sk[c]), probekey = pk[r],
                                             value = round(sub[idx], 6), type = type))   # no float noise in the file
      tot <- tot + length(idx)
    }
  }
  bump("tcgai", type, tot); tot
}
keep_nonna <- function(x) !is.na(x)
keep_nonzero <- function(x) is.na(x) | x != 0

## columns of a cohort's files -> one matrix with T2 sample ids
cohort_matrix <- function(type, C, fkeys, rd) {
  parts <- list()
  for (fk in fkeys) {
    m <- COLMAP[[type]][[paste(C, fk)]]; if (is.null(m)) next
    r <- rd(FL[[C]][[fk]])
    mm <- m[match(colnames(r$M), col)]               # columns of this file -> sample ids
    sel <- which(!is.na(mm$sample))
    r$M <- r$M[, sel, drop = FALSE]; colnames(r$M) <- mm$sample[sel]
    parts[[fk]] <- r
  }
  if (!length(parts)) return(NULL)
  ## row ids can differ between a cohort's tumor and normal file
  ids <- unique(unlist(lapply(parts, `[[`, "ids")))
  M <- do.call(cbind, lapply(parts, function(r) { x <- r$M[match(ids, r$ids), , drop = FALSE]; x }))
  stopifnot(!anyDuplicated(colnames(M)))
  list(ids = ids, M = M, nonfinite = sum(sapply(parts, `[[`, "nonfinite")))
}
