if ("rna" %in% TYPES) {
  say("== rna ==")
  idsets <- lapply(COH, function(C) read_ids(FL[[C]]$tpm))
  common <- Reduce(intersect, idsets)
  nall <- length(unique(unlist(idsets)))
  drop_log("rna genes not in all cohort TPM files", nall - length(common),
           sprintf("(kept %d common)", length(common)))
  if (SUBSET_GENES > 0) common <- head(common, SUBSET_GENES)
  rm(idsets)
  nneg <- 0; nmap_miss <- 0
  for (C in COH) {
    say("  rna", C)
    cm <- cohort_matrix("rna", C, "tpm", function(f) read_mat(f))
    keepg <- cm$ids %in% common
    M <- cm$M[keepg, , drop = FALSE]; ids <- cm$ids[keepg]; rm(cm)
    nneg <- nneg + sum(M < 0, na.rm = TRUE); M[!is.na(M) & M < 0] <- 0
    ## collapse_ensembl_to_hgnc() turns a non-finite cell into 0 (ensembl_to_hgnc.R), which would
    ## read back as "unexpressed", not "missing": refuse a TPM file with NA cells (none measured)
    if (anyNA(M)) stop(sprintf("rna %s: %d NA cells in the TPM matrix; the collapse would store them as 0", C, sum(is.na(M))))
    nmap_miss <- nmap_miss + sum(!ids %in% names(SYM))
    expr <- as.data.table(M); expr[, id := ids]; setcolorder(expr, "id"); rm(M)
    coll <- collapse_ensembl_to_hgnc(expr, hgmap, from_log = TRUE, log_base = 2, log_offset = 1,
                                     relog_offset = 1, verbose = FALSE)
    rm(expr)
    P <- as.matrix(coll[, -1]); rownames(P) <- coll$probe; rm(coll)
    n <- insert_mat(P, "rna", keep_nonzero)
    say(sprintf("    %s: %d probes x %d samples, %s tcgai rows", C, nrow(P), ncol(P), format(n, big.mark = ",")))
    rm(P); gc(FALSE)
  }
  drop_log("rna negative cells clamped to 0", nneg)
  drop_log("rna Ensembl ids without symbol (kept under their id)", nmap_miss)
}

