    PM[[C]] <- cm; nonfin <- nonfin + cm$nonfinite
    cnt[[C]] <- data.table(id = cm$ids, nn = rowSums(!is.na(cm$M)))
  }
  cnt <- rbindlist(cnt)[, .(nn = sum(nn)), by = id]
  cnt[, sym := sym_of(id)]
  cnt[, keep := pick_by_symbol(id, sym, nn)]
  drop_log("prot Ensembl ids dropped (symbol shared, fewer non-NA values)", sum(!cnt$keep),
           paste(head(cnt[keep == FALSE, paste0(id, "->", sym)], 4), collapse = ","))
  kept <- cnt[keep == TRUE]
  drop_log("prot non-finite cells set to NA", nonfin)
  drop_log("prot Ensembl ids without symbol (kept under their id)", sum(!cnt$id %in% names(SYM)))
  for (C in COH) {
    cm <- PM[[C]]; sel <- cm$ids %in% kept$id
    M <- cm$M[sel, , drop = FALSE]
    rownames(M) <- paste0(kept$sym[match(cm$ids[sel], kept$id)], ".prot")
    n <- insert_mat(M, "prot", keep_nonna)
    say(sprintf("    %s: %d probes x %d samples, %s rows", C, nrow(M), ncol(M), format(n, big.mark = ",")))
  }
  rm(PM, cnt, kept); gc(FALSE)
}

