  PM <- list(); cn <- list(); nonfin <- 0; ndupfile <- 0
  for (C in COH) {
    cm <- cohort_matrix("phospho", C, c("phos_T", "phos_N"), rd_sub)
    nonfin <- nonfin + cm$nonfinite
    pi <- parse_phospho_id(cm$ids)
    pi[, sym := sym_of(ensg)]
    pi[, nn := rowSums(!is.na(cm$M))]
    pi[, r := .I]
    ## (sym, site, ensp) unique within a file; otherwise keep the row with more non-NA
    pi[, trip := paste(sym, site, ensp, sep = "\r")]
    if (anyDuplicated(pi$trip)) {
      setorder(pi, trip, -nn, r)
      dup <- duplicated(pi$trip); ndupfile <- ndupfile + sum(dup)
      pi <- pi[!dup]
    }
    PM[[C]] <- list(info = pi, M = cm$M[pi$r, , drop = FALSE])
    cn[[C]] <- pi[, .(sym, site, ensp, nn)]
  }
  cn <- rbindlist(cn)[, .(nn = sum(nn)), by = .(sym, site, ensp)]
  cn[, keep := pick_ensp(cn)]
  drop_log("phospho duplicate (gene, ENSP, site) rows within a file", ndupfile)
  drop_log("phospho (gene, site) ENSP variants dropped (fewer non-NA values)", sum(!cn$keep),
           sprintf("(%d (gene,site) pairs with several ENSP)", cn[, .N, by = .(sym, site)][N > 1, .N] ))
  keepkey <- cn[keep == TRUE, paste(sym, site, ensp, sep = "\r")]
  drop_log("phospho non-finite cells set to NA", nonfin)
  for (C in COH) {
    pi <- PM[[C]]$info; sel <- pi$trip %in% keepkey
    M <- PM[[C]]$M[sel, , drop = FALSE]
    rownames(M) <- phospho_probe(pi$sym[sel], pi$site[sel])
    stopifnot(!anyDuplicated(rownames(M)))
    n <- insert_mat(M, "phospho", keep_nonna)
    say(sprintf("    %s: %d probes x %d samples, %s rows", C, nrow(M), ncol(M), format(n, big.mark = ",")))
    PM[[C]] <- NULL
  }
  rm(PM, cn); gc(FALSE)
}

## ============================================================================
## 7. cnv (protein-coding genes)
## ============================================================================
if ("cnv" %in% TYPES) {
  say("== cnv ==")
  PM <- list(); cnt <- list(); nonfin <- 0; npc_drop <- 0
  for (C in COH) {
    cm <- cohort_matrix("cnv", C, "cnv", function(f) read_mat(f))
    pc <- !is.na(GTYPE[cm$ids]) & GTYPE[cm$ids] == "protein_coding"
    npc_drop <- npc_drop + sum(!pc)
    if (SUBSET_GENES > 0) pc <- pc & cumsum(pc) <= SUBSET_GENES
    nonfin <- nonfin + cm$nonfinite
    PM[[C]] <- list(ids = cm$ids[pc], M = cm$M[pc, , drop = FALSE])
    cnt[[C]] <- data.table(id = PM[[C]]$ids, nn = rowSums(!is.na(PM[[C]]$M)))
  }
  drop_log("cnv genes not protein_coding (summed over cohort files)", npc_drop)
  cnt <- rbindlist(cnt)[, .(nn = sum(nn)), by = id]
  cnt[, sym := sym_of(id)]
  cnt[, keep := pick_by_symbol(id, sym, nn)]
  drop_log("cnv Ensembl ids dropped (symbol shared, fewer non-NA values)", sum(!cnt$keep))
  drop_log("cnv non-finite cells set to NA", nonfin)
  kept <- cnt[keep == TRUE]
  for (C in COH) {
    sel <- PM[[C]]$ids %in% kept$id
    M <- PM[[C]]$M[sel, , drop = FALSE]
    rownames(M) <- paste0(kept$sym[match(PM[[C]]$ids[sel], kept$id)], ".cnv")
    n <- insert_mat(M, "cnv", keep_nonna)
    say(sprintf("    %s: %d probes x %d samples, %s rows", C, nrow(M), ncol(M), format(n, big.mark = ",")))
  }
  rm(PM, cnt, kept); gc(FALSE)
}

## ============================================================================
## 8. mut (binary) and fmut (MAF)
## ============================================================================
if ("mut" %in% TYPES) {
  say("== mut ==")
  for (C in COH) {
    cm <- cohort_matrix("mut", C, "mut", function(f) read_mat(f))
    M <- cm$M; M[is.na(M)] <- 0
    sym <- sym_of(cm$ids)
    dup <- sym %in% sym[duplicated(sym)]
    if (any(dup)) {
      D <- as.data.table(M[dup, , drop = FALSE]); D[, sym := sym[dup]]
      Dm <- D[, lapply(.SD, max), by = sym]
      M <- rbind(M[!dup, , drop = FALSE], as.matrix(Dm[, -1])); sym <- c(sym[!dup], Dm$sym)
    }
    rownames(M) <- paste0(sym, ".mut")
    n <- insert_mat(M, "mut", function(x) x == 1)
    say(sprintf("    %s: %d probes x %d samples, %s rows", C, nrow(M), ncol(M), format(n, big.mark = ",")))
  }
}
if ("fmut" %in% TYPES) {
  say("== fmut ==")
  nbad <- 0; nnohugo <- 0; tot <- 0; badids <- character(0)
  for (C in COH) {
    maf <- fread(FL[[C]]$maf, sep = "\t", quote = "", colClasses = "character", na.strings = NULL,
                 select = c("Hugo_Symbol", "aaChange", "Variant_Classification", "Tumor_Sample_Barcode"))
    maf[, (names(maf)) := lapply(.SD, function(x) sub("\r$", "", x))]
    ok <- maf$Tumor_Sample_Barcode %in% samples_dt[cancer_type == C & !normal, sample]
    if (any(!ok)) { nbad <- nbad + sum(!ok); badids <- c(badids, unique(maf$Tumor_Sample_Barcode[!ok])) }
    maf <- maf[ok]
    nh <- !nzchar(maf$Hugo_Symbol) | is.na(maf$Hugo_Symbol); nnohugo <- nnohugo + sum(nh); maf <- maf[!nh]
    maf[, aaChange := fifelse(aaChange %in% c("", "NA", "."), "NA", aaChange)]
    value <- fmut_value(maf$Hugo_Symbol, maf$aaChange, maf$Variant_Classification)
    probe <- paste0(maf$Hugo_Symbol, ".fmut")
    for (lo in seq(1, length(probe), by = 500000L)) {
      hi <- min(lo + 499999L, length(probe)); ix <- lo:hi
      dbAppendTable(con, "tcgacati", data.frame(samplekey = unname(sample_key[maf$Tumor_Sample_Barcode[ix]]),
                    probekey = assign_keys(probe[ix], "fmut"), value = value[ix], type = "fmut"))
    }
    tot <- tot + length(probe); bump("tcgacati", "fmut", length(probe))
    say(sprintf("    %s: %s fmut rows", C, format(length(probe), big.mark = ",")))
  }
  drop_log("fmut rows whose Tumor_Sample_Barcode is not a tumor sample of the cohort", nbad,
           paste(head(unique(badids), 4), collapse = ","))
  drop_log("fmut rows without Hugo_Symbol", nnohugo)
}

## probe-name checks (SPEC section 3)
ptype <- unlist(mget(probe_names, envir = probe_type_env), use.names = FALSE)
suffix_re <- "\\.(prot|phospho|cnv|mut|fmut)$"
bare <- probe_names[ptype == "rna"]
stopifnot(!any(grepl(suffix_re, bare)))
typed <- probe_names[ptype != "rna"]
stopifnot(all(grepl(suffix_re, typed)))
ndot_bare <- sum(grepl(".", bare, fixed = TRUE))
ndot_typed <- sum(grepl(".", sub(suffix_re, "", typed), fixed = TRUE))
drop_log("INFO probe names with a dot in the symbol part (rna bare / typed)", ndot_bare, sprintf("/ %d typed", ndot_typed))
stopifnot(!anyDuplicated(probe_names))

## ============================================================================
## 9. clinpheno
## ============================================================================
say("== clinpheno ==")
SURV <- c(OS_days = "OS.time", OS_event = "OS", PFS_days = "PFI.time", PFS_event = "PFI")
clin_list <- list(); nacoerce <- 0
for (C in COH) {
  m <- META[[C]]; dt <- copy(m$dt); ty <- m$types
  dt[, (c("Tumor", "Normal")) := NULL]; ty <- ty[!names(ty) %in% c("Tumor", "Normal")]
  case <- dt$idx; dt[, idx := NULL]; ty <- ty[names(dt)]
  nn <- norm_clin_names(names(dt)); stopifnot(!anyDuplicated(nn))
  names(ty) <- nn; setnames(dt, nn)
  for (o in names(SURV)) if (o %in% names(dt)) { setnames(dt, o, SURV[[o]]); names(ty)[names(ty) == o] <- SURV[[o]] }
  if ("POLE" %in% names(dt)) { setnames(dt, "POLE", "POLE_status"); names(ty)[names(ty) == "POLE"] <- "POLE_status" }
  for (j in names(dt)) {
    v <- dt[[j]]
    if (j %in% c("OS", "PFI")) { x <- coerce_event(v); stopifnot(all(x %in% c(0, 1) | is.na(x))); nacoerce <- nacoerce + sum(is.na(x) & !is.na(v)); set(dt, j = j, value = x) }
    else if (ty[[j]] == "CON") { x <- suppressWarnings(as.numeric(v)); nacoerce <- nacoerce + sum(is.na(x) & !is.na(v)); set(dt, j = j, value = x) }
    else set(dt, j = j, value = as.character(v))        # BIN / ORD / other: text
  }
  set(dt, j = "case", value = case)     # not dt[, case := case]: a meta column named `case` would win
  clin_list[[C]] <- dt
}
drop_log("clinical CON/event values not numeric (set to NA)", nacoerce)
## class conflicts across cohorts
cls <- rbindlist(lapply(clin_list, function(d) data.table(col = names(d), cl = vapply(d, function(x) class(x)[1], ""))))
cc <- unique(cls)[, .N, by = col][N > 1]; if (nrow(cc)) stop("clinical class conflict: ", paste(cc$col, collapse = ","))

smp_c <- split(samples_dt, samples_dt$cancer_type)
parts <- list()
for (C in COH) {
  s <- smp_c[[C]]; d <- clin_list[[C]]
  X <- d[match(s$case, d$case)]
  stopifnot(!anyNA(X$case))
  nm <- which(s$normal)
  for (j in setdiff(names(X), c("case", NORMAL_KEEP))) if (length(nm)) set(X, i = nm, j = j, value = NA)
  X[, case := NULL]
  parts[[C]] <- cbind(data.table(sample = s$sample, case = s$case, cancer_type = C, study = study_of(C),
                                 sample_type = s$sample_type), X)
}
clinpheno <- rbindlist(parts, use.names = TRUE, fill = TRUE)
## names equal to a probe name or a reserved word get _clin
meta_cols <- setdiff(names(clinpheno), c("sample", "case", "cancer_type", "study", "sample_type"))
nn2 <- clin_collide(meta_cols, probe_names)
if (any(nn2 != meta_cols)) {
  drop_log("INFO clinical columns renamed with _clin (collision)", sum(nn2 != meta_cols),
           paste(meta_cols[nn2 != meta_cols], collapse = ","))
  setnames(clinpheno, meta_cols, nn2)
}
stopifnot(!anyDuplicated(names(clinpheno)))
for (j in names(clinpheno)) if (is.character(clinpheno[[j]]))
  set(clinpheno, j = j, value = iconv(clinpheno[[j]], "UTF-8", "UTF-8", sub = " "))
stopifnot(all(clinpheno$OS %in% c(0, 1, NA)), all(clinpheno$PFI %in% c(0, 1, NA)))
clin_cols <- setdiff(names(clinpheno), "sample")
say("clinpheno:", nrow(clinpheno), "rows x", ncol(clinpheno), "cols")

## ============================================================================
## 10. dimension tables
## ============================================================================
probes_tbl <- data.frame(key = seq_along(probe_names), probe = probe_names, stringsAsFactors = FALSE)
allp <- c(probe_names, clin_cols)
stopifnot(!anyDuplicated(allp))
allprobes_tbl <- data.frame(key = seq_along(allp), probe = allp, stringsAsFactors = FALSE)
dbWriteTable(con, "samples", as.data.frame(samples_dt[, .(key, sample)]), overwrite = TRUE)
dbWriteTable(con, "probes", probes_tbl, overwrite = TRUE)
dbWriteTable(con, "allprobes", allprobes_tbl, overwrite = TRUE)
dbWriteTable(con, "clinpheno", as.data.frame(clinpheno), overwrite = TRUE)
dbWriteTable(con, "tested", as.data.frame(tested), overwrite = TRUE)

LC <- c(BRCA = "breast invasive carcinoma", CCRCC = "clear cell renal cell carcinoma",
        COAD = "colon adenocarcinoma", GBM = "glioblastoma", HNSCC = "head and neck squamous cell carcinoma",
        LSCC = "lung squamous cell carcinoma", LUAD = "lung adenocarcinoma",
        OV = "high-grade serous ovarian carcinoma", PDAC = "pancreatic ductal adenocarcinoma",
        UCEC = "uterine corpus endometrial carcinoma")
cohorts_tbl <- data.frame(cohort = COH, lcohort = unname(LC[COH]),
                          cohortstring = sprintf("%s (%s, %s)", COH, LC[COH], study_of(COH)),
                          stringsAsFactors = FALSE)
dbWriteTable(con, "cohorts", cohorts_tbl, overwrite = TRUE)

REF <- paste("Li Y et al., Proteogenomic data and resources for pan-cancer analysis. Cancer Cell 2023;",
             "41:1397-1406 (CPTAC Pan-Cancer harmonized data freeze v1, BCM pipeline, GENCODE v34).",
             "Data generated by the National Cancer Institute Clinical Proteomic Tumor Analysis Consortium (CPTAC).")
PDCURL <- "https://pdc.cancer.gov/pdc/cptac-pancancer"
tdef <- list(
  rna = c("Gene-level RNA-seq expression, BCM pipeline, Ensembl genes collapsed to HGNC symbols (summed in linear space), log2(TPM+1). Tumors and normal adjacent tissue.", "CD8A",
          "https://pdc.cancer.gov/pdc/cptac-pancancer ; https://kb.linkedomics.org/download", "<C>-gene_TPM[_removed_circRNA]_tumor_normal_raw_log2(x+1)_BCM.txt"),
  prot = c("Gene-level protein abundance from TMT mass spectrometry, log2 intensity normalized to the cohort's pooled reference (BCM harmonized). Comparable within a cohort; across cohorts only with care, each cohort has its own reference. Missing when the protein was not quantified.", "CD8A.prot",
           PDCURL, "<C>_proteomics_gene_abundance_log2_reference_intensity_normalized_{Tumor,Normal}.txt"),
  phospho = c("Phosphosite abundance (one site per probe, GENE_S123.phospho), log2 intensity normalized to the cohort's reference, BCM harmonized. Missing when the site was not quantified.", "MAPK1_Y187.phospho",
              PDCURL, "<C>_phospho_site_abundance_log2_reference_intensity_normalized_{Tumor,Normal}.txt"),
  cnv = c("Gene-level somatic copy number from whole-exome sequencing, log2 ratio tumor/normal (0 = neutral), protein-coding genes, BCM pipeline.", "ERBB2.cnv",
          PDCURL, "<C>_WES_CNV_gene_ratio_log2.txt"),
  mut = c("Somatic mutation present (1) or absent (0) per gene, whole-exome sequencing, BCM pipeline.", "TP53.mut",
          PDCURL, "<C>_somatic_mutation_gene_level_binary.txt"),
  fmut = c("Somatic mutations spelled out: gene, protein change and variant class (TP53_p.R273H_Missense_Mutation), from the BCM MAF.", "TP53.fmut",
           PDCURL, "<C>_somatic_mutation.maf"))
tt <- intersect(names(tdef), TYPES)
## the bibliography (CPTAC/references.json, validated); the Li 2023 paper's PMID goes into every types.reference
REFS_JSON <- t2_references_json(file.path(CP_DIR, "references.json"))
LI_PMID <- local({
  r <- Filter(function(r) identical(r$doi, "10.1016/j.ccell.2023.06.009"), jsonlite::fromJSON(REFS_JSON, simplifyVector = FALSE))
  if (length(r) != 1 || !nzchar(paste0(r[[1]]$pmid, collapse = ""))) stop("CPTAC/references.json: need exactly one record for doi 10.1016/j.ccell.2023.06.009, with a pmid")
  r[[1]]$pmid
})
REF <- paste0(REF, " PMID:", LI_PMID)
## types, datatypes and sparse model per type in one table (t2_build_lib.R writes all three)
type_spec <- data.frame(type = tt, description = sapply(tdef[tt], `[`, 1), example = sapply(tdef[tt], `[`, 2),
                        reference = REF, source_url = sapply(tdef[tt], `[`, 3), source_file = sapply(tdef[tt], `[`, 4),
                        ## the word a plot title uses for the type ("" = a bare name needs none)
                        label = unname(c(rna = "", prot = "protein", phospho = "phosphosite", cnv = "CNA",
                                         mut = "mutation", fmut = "mutation")[tt]),
                        r_datatype = ifelse(tt %in% c("mut", "fmut"), "factor", "numeric"),
                        sparse = tt %in% c("rna", "mut"), default_value = ifelse(tt %in% c("rna", "mut"), 0, NA_real_),
                        ## how a TESTED sample without a stored value may be served (the api's values?fill=):
                        ## proteome and phosphoproteome gaps are "not detected" (no quantifiable PSM in the TMT
                        ## plex, below the detection floor: the low expressers), so zero or the per-cohort floor
                        ## are meaningful options; every other type's gap is plain missing. Untested = NA always.
                        fill_options = ifelse(tt %in% c("prot", "phospho"), "na|zero|floor", "na"),
                        stringsAsFactors = FALSE, row.names = NULL)
t2_write_types(con, type_spec)
ABOUT <- paste("T2 CPTAC Pan-Cancer: the harmonized proteogenomic data freeze of the National Cancer Institute's Clinical Proteomic Tumor Analysis Consortium (CPTAC),",
               "ten cancer cohorts (BRCA, CCRCC, COAD, GBM, HNSCC, LSCC, LUAD, OV, PDAC, UCEC) with tumors and normal adjacent tissue.",
               "RNA-seq expression, TMT mass-spectrometry protein and phosphosite abundance, copy number and somatic mutations were processed by one pipeline (BCM, GENCODE v34).",
               "Protein and phosphosite values are comparable within a cohort; across cohorts only with care, since each cohort has its own reference.",
               "Overall survival (OS) and progression-free interval (PFI) are clinical variables; select one as the X variable for a Kaplan-Meier analysis.")
t2_write_meta(con,
  meta = list(title = "T2: CPTAC Pan-Cancer Proteogenomics (2023 harmonized freeze)", label = "CPTAC Pan-Cancer",
              cohort_col = "cancer_type", subtype_col = "", sampletype_col = "sample_type",
              normal_label = "Solid Tissue Normal", heme_values = "",
              sampletype_levels = c("Primary Tumor", "Solid Tissue Normal"),
              default_x = "cohort", default_y = "CD8A", default_color = "sample_type", default_size = "",
              default_condition = "", default_cohorts = COH, about = ABOUT, references = REFS_JSON,
              citation = "Li Y, Dou Y, Da Veiga Leprevost F, et al. Proteogenomic data and resources for pan-cancer analysis. Cancer Cell 2023;41:1397-1406. doi:10.1016/j.ccell.2023.06.009",
              attribution = "Data used in this publication were generated by the National Cancer Institute Clinical Proteomic Tumor Analysis Consortium (CPTAC).",
              about_url = "https://pdc.cancer.gov/pdc/cptac-pancancer"),
  tte = list(
    t2_tte("OS", "Overall Survival", "OS", "OS.time", "days",
           "Overall survival from the CPTAC cohort meta files (OS_event: 1 = death, 0 = censored; OS_days: follow-up in days)."),
    t2_tte("PFI", "Progression-Free Interval", "PFI", "PFI.time", "days",
           "Progression-free survival from the CPTAC cohort meta files (PFS_event: 1 = progression or death, 0 = censored; PFS_days: days). Named PFI to match the TCGA endpoint handle.")))

